interface User {
  id: string;
  name: string;
}

interface Timestamped {
  createdAt: Date;
  updatedAt: Date;
}

type AuditedUser = User & Timestamped;

const row: AuditedUser = {
  id: "u-1",
  name: "Ada",
  createdAt: new Date(),
  updatedAt: new Date(),
};

type Serializable = { toJSON(): string };
type Identifiable = { id: string };

type Entity = Serializable & Identifiable;

function createEntity(id: string, data: object): Entity {
  return {
    id,
    toJSON() {
      return JSON.stringify({ id, ...data });
    },
  };
}

type Bad = { id: string } & { id: number };
