type Cat = { kind: "cat"; meow(): void };
type Dog = { kind: "dog"; bark(): void };
type Named = { name: string };

type NamedPet = (Cat | Dog) & Named;

function greet(pet: NamedPet): string {
  return `${pet.name} (${pet.kind})`;
}
